cat > /app/start.sh <<'SH'
#!/bin/sh
set -eu
: > /app/state.lock
[ -f /app/state.json ] || echo '{"users":{},"tokens":{},"workspaces":{},"channels":{},"messages":{},"events":{},"members":{},"dms":{},"reactions":{}}' > /app/state.json
pids=""
for n in 0 1 2; do NODE_ID=$n PORT=$((8000+n)) python3 /app/server.py & pids="$pids $!"; done
